// 文件: app/products/page.js
// 这是一个 React Server Component，无需 'use client' 指令
import { Suspense } from 'react';
import ProductList from './ProductList'; // 这是一个客户端组件

// 服务端数据获取函数，可被多个组件复用
async function getProducts() {
  // 使用扩展的 fetch，设置基于时间的缓存重验证（ISR）
  const res = await fetch('https://api.example.com/products', {
    next: { revalidate: 3600 } // 每小时重新验证一次
  });

  if (!res.ok) {
    // 这个错误会由最接近的 error.js 处理
    throw new Error('Failed to fetch products');
  }

  return res.json();
}

// 这个 Server Action 可以在客户端组件中调用，用于更新数据
export async function likeProduct(productId) {
  'use server'; // 标记为 Server Action

  // 在这里执行安全的服务端操作（如数据库更新）
  console.log(`Liking product ${productId} on the server...`);
  // 假设调用了数据库 API
  // await db.products.update({ id: productId }, { $inc: { likes: 1 } });

  // 重验证与特定标签关联的所有数据缓存
  revalidateTag('products');
}

export default async function ProductsPage() {
  // 在服务端组件中直接 async 获取数据
  const initialProducts = await getProducts();

  return (
    <div>
      <h1>Our Products</h1>
      {/* 使用 Suspense 实现流式加载，提升用户体验 */}
      <Suspense fallback={<div>Loading more products...</div>}>
        {/* 将服务端获取的数据作为 props 传给客户端组件 */}
        <ProductList initialProducts={initialProducts} />
      </Suspense>
    </div>
  );
}

// 文件: app/products/ProductList.js
'use client'; // 标记为客户端组件

import { useState } from 'react';
import { likeProduct } from './page'; // 导入 Server Action

// 客户端组件接收服务端组件传递的数据作为初始状态
export default function ProductList({ initialProducts }) {
  const [products, setProducts] = useState(initialProducts);
  const [liking, setLiking] = useState(null);

  const handleLike = async (productId) => {
    setLiking(productId);
    try {
      // 调用 Server Action 来执行服务端操作
      await likeProduct(productId);
      // 乐观更新：直接在客户端更新UI，提供即时反馈
      setProducts(prev => prev.map(p => 
        p.id === productId ? { ...p, likes: p.likes + 1 } : p
      ));
    } catch (error) {
      console.error('Failed to like product:', error);
      // 回滚乐观更新
      setProducts(initialProducts);
    } finally {
      setLiking(null);
    }
  };

  return (
    <ul>
      {products.map(product => (
        <li key={product.id}>
          {product.name} - Likes: {product.likes}
          <button 
            onClick={() => handleLike(product.id)}
            disabled={liking === product.id}
          >
            {liking === product.id ? 'Liking...' : 'Like'}
          </button>
        </li>
      ))}
    </ul>
  );
}

